function renderBus(s,v){const bus=$('#messageBus'),old=bus.scrollTop,atBottom=bus.scrollHeight-bus.scrollTop-bus.clientHeight<50;const rows=v.messages.map((m,index)=>({m,index})).filter(({m})=>messageFilter==='all'||m.sender===messageFilter);bus.innerHTML=rows.length?rows.map(({m,index})=>{let text=m.reason||m.error||'',type=m.type;if(type==='PROPOSE')text=(m.reason||'')+' '+m.proposal.events.map(e=>(s.flights.find(f=>f.id===e.flight)?.callsign||e.flight)+' '+clock(e.landing,s)+' → '+(e.alternate||e.stand)).join(' · ');else if(type==='FALLBACK')text=(m.reason||'')+(m.proposal_id?' · A fully checked candidate was selected.':' · No valid generated candidate. No plan committed.');else if(m.counter_id)text+=' A revised plan is ready for review.';return `<article class="message"><div class="message-meta"><strong>${String(index+1).padStart(2,'0')} · ${esc((m.sender||'coordinator').toUpperCase())} → ALL</strong><span class="type-chip ${m.type.toLowerCase()}">${esc(type.replaceAll('_',' '))}</span></div><p>${esc(text)}</p><details><summary>Structured message</summary><pre>${esc(JSON.stringify(m,null,2))}</pre></details></article>`;}).join(''):`<div class="empty-state"><b>${current?'No matching messages yet.':'The agents are ready.'}</b>${current?'Advance the playback to inspect the next decision.':'Configure a flight cohort, then run recovery to watch the three domains exchange proposals.'}</div>`;bus.scrollTop=timer&&atBottom?bus.scrollHeight:old;}
