function selectField(key,label,value,options){return `<label class="field">${label}<select data-key="${key}" aria-label="${label}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function boolField(key,label,value){return `<label class="check-field"><input data-key="${key}" aria-label="${label}" type="checkbox" ${value?'checked':''}>${label}</label>`;}
function editFlight(i){editingIndex=i;const f=draft.flights[i],n=(k,t,min=0,max=20000)=>numField(k,t,f[k],min,max),section=(title,html)=>`<section class="editor-section"><h3>${title}</h3><div class="editor-fields">${html}</div></section>`;$('#editorTitle').textContent='Edit '+(f.callsign||f.id);$('#flightFields').innerHTML=section('Flight & arrival',`<label class="field">Callsign<input data-key="callsign" aria-label="Callsign" pattern="[A-Za-z0-9-]+" maxlength="16" value="${esc(f.callsign||'')}" required></label><label class="field">Carrier / airline<input data-key="carrier" aria-label="Carrier / airline" maxlength="40" value="${esc(RecoveryPresentation.carrier(f))}" required></label><label class="field">Origin<input data-key="origin" aria-label="Origin" pattern="[A-Za-z0-9]+" maxlength="5" value="${esc(f.origin||'')}" required></label><label class="field">Aircraft type (optional)<input data-key="aircraft_type" aria-label="Aircraft type" maxlength="40" value="${esc(f.aircraft_type||'')}"></label>`+n('eta','ETA (T+ min)',0,480)+selectField('operation','Planned action',f.operation,[['arrive','Arrive here'],['divert','Divert to alternate']])+selectField('wake','Wake category',f.wake,[['small','Small'],['large','Large'],['heavy','Heavy'],['super','Super (A380)']])+selectField('runway','Assigned runway',f.runway,draft.atc.runways.map(r=>[r.id,r.id]))+n('approach_speed_kts','Approach groundspeed (kt)',60,250))+section('Fuel protection & diversion',n('fuel','Fuel on board (kg)')+n('reserve','Entered final reserve (kg)',0,15000)+n('burn_per_min','Holding burn (kg/min)',1,200)+n('cruise_burn_per_min','Normal cruise burn (kg/min)',1,200)+n('cruise_speed_kts','Cruise groundspeed (kt)',100,600)+n('destination_fuel','Fuel to destination (kg)',0,5000)+selectField('alternate_id','Alternate',f.alternate?.id,draft.alternate_options.map(a=>[a.id,a.id]))+n('alternate_approach_fuel','Alternate approach fuel (kg)',0,5000)+n('alternate_approach_minutes','Alternate approach time (min)',0,60)+boolField('alternate_required','Alternate required',f.alternate_required))+section('Weather assessment',numField('trip_fuel','Planned trip fuel for contingency (kg)',f.trip_fuel,0,100000)+numField('crew_duty_elapsed','Elapsed duty since report at T0 (min)',f.crew_duty_elapsed,0,780)+numField('holding_turbulence','Holding turbulence (0 smooth–3 severe; assumed)',f.holding_turbulence??1,0,3)+boolField('weather_assessed','Weather assessed (simulation)',f.weather?.assessed)+boolField('weather_severe','Severe / intense storm',f.weather?.severe)+numField('weather_clearance_miles','Storm clearance (miles)',f.weather?.clearance_miles,0,200))+section('Turnaround, flight crew & connections',n('turnaround','Turnaround (min)',0,120)+n('next_departure','Scheduled gate departure (T+ min)',0,600)+n('next_flight_minutes','Next flight block time (min)',1,600)+n('crew_duty_remaining','Remaining FDP from T0 (min)',0,840)+n('crew_flight_remaining','Remaining flight-time budget (min)',0,540)+n('current_flight_remaining','Current flight remaining (min)',0,120)+n('connections','Connecting passengers',0,500)+n('connection_departure','Connection departs (T+ min)',0,600));$('#flightError').textContent='';$('#editorDialog').showModal();}
$('#flightForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){const invalid=form.querySelector('input:invalid,select:invalid');$('#flightError').textContent=(invalid.getAttribute('aria-label')||'Input')+': '+invalid.validationMessage;invalid.focus();return;}const f=clone(draft.flights[editingIndex]);f.weather=f.weather||{};for(const el of $$('#flightFields [data-key]')){const k=el.dataset.key;if(k==='alternate_id')f.alternate=clone(draft.alternate_options.find(a=>a.id===el.value));else if(k==='weather_assessed')f.weather.assessed=el.checked;else if(k==='weather_severe')f.weather.severe=el.checked;else if(k==='weather_clearance_miles')f.weather.clearance_miles=Csv.num(el.value);else f[k]=el.type==='checkbox'?el.checked:el.type==='number'?Csv.num(el.value):['operation','wake','runway'].includes(k)?el.value:el.value.trim().toUpperCase();}if(draft.flights.some((x,i)=>i!==editingIndex&&x.callsign===f.callsign)){$('#flightError').textContent='Use a distinct callsign for each flight.';return;}f.user_edited=true;draft.flights[editingIndex]=f;$('#editorDialog').close();invalidate('Flight updated. Run recovery to evaluate the revised inputs.');};
function showInfo(html){$('#infoContent').innerHTML=html;$('#infoDialog').showModal();}
function chooseCSV(){$('#csvFile').value='';$('#csvFile').click();}
function importProgress(message,fraction){$('#importProgress').textContent=message;$('#importProgressBar').style.width=Math.round(Math.max(0,Math.min(1,fraction||0))*100)+'%';}
function inspectFile(file,filters={}){if(importWorker)importWorker.terminate();selectedFile=file;importState={mode:null,records:[],selected:new Set(),file:file.name};$('#importContent').innerHTML='';$('#importError').textContent='';$('#confirmImport').disabled=true;if(!$('#importDialog').open)$('#importDialog').showModal();importProgress('Reading '+file.name+' locally…',0);importWorker=new Worker('csv-worker.js');const id=++importId;importWorker.onmessage=({data:x})=>{if(x.id!==id)return;if(x.cohort_token!==undefined&&x.cohort_token!==importState.cohortToken)return;if(x.type==='progress'){importProgress('Reading '+fmt(x.rows)+' rows · '+Math.round(x.progress*100)+'% · file stays on your device',x.progress);return;}if(x.type==='error'){$('#importError').textContent=x.message;importProgress('Import stopped. Your current manifest is unchanged.',0);return;}if(x.type==='inspected'){Object.assign(importState,x);if(x.mode==='dot'){renderDotImport();requestCohort(importState.anchors[0]);}else{importState.records=x.records;importState.selected=new Set(x.records.slice(0,Math.min(draft.flights.length,12)).map(r=>r.index));renderOperationalImport();importProgress(fmt(x.rows)+' rows read. '+x.records.length+' preview rows available'+(x.skipped?' (first 1,000 shown).':'.'),1);}}else if(x.type==='cohort'){importState.loading=false;$('#seedSelect').disabled=false;importState.records=x.records;importState.total=x.total;importState.selected=new Set([...x.records.filter(r=>r.index===importState.anchor.index),...x.records.filter(r=>r.index!==importState.anchor.index)].slice(0,Math.min(draft.flights.length,12)).map(r=>r.index));renderSelection();importProgress(fmt(importState.rows)+' rows scanned · '+fmt(importState.qualifying)+' qualifying seeds · '+x.total+' nearby arrivals found.',1);}};importWorker.onerror=()=>{$('#importError').textContent='The CSV worker failed. Choose a UTF-8 CSV and try again.';};importWorker.postMessage({id,type:'inspect',file,filters});}
function requestCohort(anchor){importState.anchor=anchor;importState.cohortToken=(importState.cohortToken||0)+1;importState.loading=true;$('#seedSelect').disabled=true;$('#selectionArea').innerHTML='<div class="empty-state">Finding nearby arrivals…</div>';$('#confirmImport').disabled=true;importProgress('Finding arrivals at '+anchor.row.DESTINATION_AIRPORT+' on the same flight date, within ±60 min…',0);importWorker.postMessage({id:importId,type:'cohort',anchor,cohort_token:importState.cohortToken});}
function assumptionHTML(required){return `<label class="import-assumptions"><input id="useDefaults" type="checkbox"><span><b>Apply workbook limits and the declared scenario assumptions${required?' (required for DOT data)':''}.</b><br>Workbook limits govern gates, runways, fuel reserves, burn and duty limits. Fuel on board, geometry, weather assessment, connections and remaining crew time still use declared assumptions. These are not measured operational facts. Blank supplied cells remain unknown.</span></label>`;}
function renderDotImport(){const anchors=importState.anchors;$('#importContent').innerHTML=`<div class="import-summary"><b>US DOT 2015 format recognised.</b> Choose a delayed seed, then select 1–12 nearby arrivals. Delay eligibility: WEATHER_DELAY &gt; 15 or LATE_AIRCRAFT_DELAY &gt; 20. Actual arrival outcomes are not used as decision inputs.</div><div class="import-controls"><label class="field wide">Eligible seed (up to 200 examples)<select id="seedSelect">${anchors.map((a,i)=>`<option value="${i}">${esc(a.row.AIRLINE+a.row.FLIGHT_NUMBER)} → ${esc(a.row.DESTINATION_AIRPORT)} · ${esc(a.row.YEAR+'-'+a.row.MONTH+'-'+a.row.DAY)} · ${esc(a.row.SCHEDULED_ARRIVAL)}</option>`).join('')}</select></label><label class="field">Find another airport<input id="seedAirport" placeholder="e.g. ORD" maxlength="5"></label><label class="field">Flight date (optional)<input id="seedDate" type="date"></label><button id="rescanSeeds" class="secondary wide">Find eligible seeds in this file</button></div><div id="selectionArea"></div>${assumptionHTML(true)}`;$('#seedSelect').onchange=e=>requestCohort(anchors[Number(e.target.value)]);$('#rescanSeeds').onclick=()=>inspectFile(selectedFile,{airport:$('#seedAirport').value.trim().toUpperCase(),date:$('#seedDate').value});}
function renderOperationalImport(){$('#importContent').innerHTML=`<div class="import-summary"><b>Operational CSV recognised.</b> Select 1–12 rows. Shared airport resources use the displayed scenario profile. Without explicit defaults, missing required flight fields block validation.</div><div id="selectionArea"></div>${assumptionHTML(false)}`;renderSelection();}
function renderSelection(){const rows=importState.records,selected=importState.selected;$('#selectionArea').innerHTML=`<div class="selection-meta"><span id="selectionCount">${selected.size} / 12 selected</span><span>${rows.length} rows shown${importState.total>rows.length?' · preview capped at 1,000':''}</span></div><div class="import-selection"><table><thead><tr><th>Select</th><th>Flight</th><th>Origin → destination</th><th>Arrival / ETA</th></tr></thead><tbody>${rows.map(record=>{const r=record.row;return `<tr><td><input type="checkbox" data-csv-row="${record.index}" aria-label="Select CSV row ${record.index}" ${selected.has(record.index)?'checked':''}></td><td>${esc(r.CALLSIGN||((r.AIRLINE||'')+(r.FLIGHT_NUMBER||''))||'Row '+record.index)}</td><td>${esc(r.ORIGIN||r.ORIGIN_AIRPORT||'—')} → ${esc(r.DESTINATION||r.DESTINATION_AIRPORT||draft.airport)}</td><td>${esc(r.SCHEDULED_ARRIVAL||r.ETA||'—')}</td></tr>`;}).join('')}</tbody></table></div>`;$('#confirmImport').disabled=!selected.size;}
$('#importDialog').addEventListener('close',()=>{if(importWorker){importWorker.terminate();importWorker=null;}});
$('#csvFile').onchange=e=>{const file=e.target.files[0];if(file)inspectFile(file);};$('#uploadBtn').onclick=chooseCSV;$('#chooseAnother').onclick=chooseCSV;
$('#importContent').addEventListener('change',e=>{if(e.target.dataset.csvRow){const index=Number(e.target.dataset.csvRow);if(e.target.checked&&importState.selected.size>=12){e.target.checked=false;$('#importError').textContent='Select at most 12 flights for one run.';return;}if(e.target.checked)importState.selected.add(index);else importState.selected.delete(index);$('#selectionCount').textContent=importState.selected.size+' / 12 selected';$('#confirmImport').disabled=!importState.selected.size;$('#importError').textContent='';}});
$('#confirmImport').onclick=()=>{try{if(importState.loading)throw Error('Wait for the selected cohort to finish loading.');const selected=importState.records.filter(r=>importState.selected.has(r.index)),defaults=$('#useDefaults').checked;if(importState.mode==='dot'&&!defaults)throw Error('DOT schedules do not contain fuel or crew budgets. Explicitly apply the labelled demo profile to proceed.');let s=importState.mode==='dot'?ScenarioIO.dotScenario(SIMULATIONS.recovery.scenario,selected,AIRPORTS):ScenarioIO.operationalScenario(draft,selected,AIRPORTS,{useDefaults:defaults});const calls=s.flights.map(f=>f.callsign);if(importState.mode==='dot'){const anchor=importState.anchor;if(!selected.some(r=>r.index===anchor.index))throw Error('Keep the chosen disruption row selected so its flight is included in the recovery plan.');s.historical_seed=clone(anchor.row);s.disruption=DisruptionIO.fromDot(anchor);s=WorkbookProfile.apply(s);}else{const supplied=s.flights;s=WorkbookProfile.apply(s);s.flights=supplied;}if(calls.some(c=>!c))throw Error('Every selected row needs a callsign.');if(new Set(calls).size!==calls.length)throw Error('Select distinct flight callsigns; duplicate rows were found.');draft=s;focusId=draft.flights[0].id;$('#importDialog').close();if(importWorker){importWorker.terminate();importWorker=null;}syncSidebar();invalidate(selected.length+' flights imported from '+importState.file+'. '+(defaults?'Operational assumptions are labelled and editable.':'Missing required inputs remain unknown.'));setTab('manifest');}catch(error){$('#importError').textContent=error.message;}};
$('#templateBtn').onclick=()=>download('operational-flights-template.csv',ScenarioIO.template(draft),'text/csv;charset=utf-8');
$('#scenarioExport').onclick=()=>download('recovery-scenario.json',JSON.stringify(draft,null,2));$('#traceExport').onclick=()=>{if(current?.result)download(current.id+'-trace.json',JSON.stringify(current,null,2));};

$('#applyCount').onclick=updateCount;$('#standCount').oninput=()=>{const n=Csv.num($('#standCount').value);if(Number.isInteger(n)&&n>=2&&n<=12)updateStands();};$$('[data-resource]').forEach(el=>el.oninput=()=>{readResources();$('#effectReopens').value=draft.atc.runway_reopens;$('#effectWeather').value=draft.atc.runways[0].weather_closed_windows[0]?.[1]||0;$('#effectEquipment').value=draft.ground.equipment_ready;invalidate();});$('#taxiBlocked').onchange=()=>{readResources();invalidate();};$('#outage').onchange=()=>invalidate();
$('#runBtn').onclick=run;$('#playBtn').onclick=play;$('#stepBtn').onclick=()=>{stopPlayback();step();};$('#resetBtn').onclick=()=>{stopPlayback();cursor=0;render();};$('#speed').onchange=()=>{if(timer){stopPlayback();timer=setInterval(step,Number($('#speed').value));}};$('#focusFlight').onchange=e=>{focusId=e.target.value;render();};$('#addFlight').onclick=()=>{$('#flightCount').value=Math.min(12,draft.flights.length+1);updateCount();};
$$('[data-tab]').forEach(el=>el.onclick=()=>setTab(el.dataset.tab));$$('[data-filter]').forEach(el=>el.onclick=()=>{messageFilter=el.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===el));renderBus(scenario(),view());});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.close){if(el.dataset.close==='scenarioDialog'){if(!validResources())return;readResources();updateStands(true);}$('#'+el.dataset.close).close();if(el.dataset.close==='importDialog'&&importWorker){importWorker.terminate();importWorker=null;}return;}if(el.dataset.turnJump){stopPlayback();cursor=Number(el.dataset.turnJump);render();}if(el.hasAttribute('data-open-settings'))$('#scenarioDialog').showModal();if(el.hasAttribute('data-open-manifest'))setTab('manifest');if(el.id==='editFlightsBtn'){setTab('manifest');$('#manifestPanel').scrollIntoView({block:'start',behavior:'smooth'});}if(el.dataset.edit!==undefined)editFlight(Number(el.dataset.edit));if(el.dataset.remove!==undefined){if(draft.flights.length<=1)return;draft.flights.splice(Number(el.dataset.remove),1);syncSidebar();invalidate('Flight removed. Run recovery to review the revised cohort.');}if(el.dataset.evidence){const r=el.dataset.evidence;if(evidenceOpen.has(r))evidenceOpen.delete(r);else evidenceOpen.add(r);renderAgents(scenario(),view());}if(el.dataset.jump){stopPlayback();cursor=Number(el.dataset.jump);render();}if(el.dataset.review){stopPlayback();if(simulationWorker){simulationWorker.terminate();simulationWorker=null;jobId++;}current=runs.find(r=>r.id===el.dataset.review);draft=clone(current.scenario);$('#outage').value=current.options?.failAgent||'';cursor=RecoveryPresentation.playback(current.result,0).total;focusId=draft.flights[0].id;syncSidebar();setTab('workspace');notice('Reviewing '+current.id+' and its recorded input snapshot. Editing inputs starts a new revision.');render();}});
$('#rulesBtn').onclick=()=>showInfo(RULES_REFERENCE_HTML);$('#provenanceBtn').onclick=()=>showInfo(`<h2>Inspectable inputs. Explicit limits.</h2><p><b>Current source:</b> ${esc(draft.source_label||'Demo profile')}.</p><pre>${esc(JSON.stringify(draft.provenance,null,2))}</pre><p>The interface is Airbus-inspired, not an official Airbus product or approved design system. Hosted rules mode is deterministic; optional local Claude mode requires the Python backend and a server credential. Domain facts are visible for review; browser panels do not provide private access controls.</p><p>CSV files are parsed locally in a background worker. Operational inputs are user assertions or explicitly applied assumptions. No file is uploaded to a server or model. Run history is kept only in this browser session.</p><p>Flight count is limited to 1–12 per run. Larger scenarios use bounded heuristic candidates, never an unconstrained negotiation loop. Missing hard-rule data blocks agreement and fallback. The three domain agents remain fixed regardless of flight count.</p><p>Wake spacing uses a named legacy profile and constant groundspeed, not a full trajectory model. Weather clearance and crew budgets are supplied inputs. Diversion uses airport-coordinate distance; it is not a live route/performance assessment. This is not operational clearance or full FAA/Part 117 compliance software.</p><p><a href="rules.json" target="_blank">Rule configuration</a> · <a href="scenario-example.json" target="_blank">Complete example scenario</a></p>`);
syncSidebar();render();

$("#settingsBtn").onclick=()=>$("#scenarioDialog").showModal();

function eventCard(e,index,s){const f=s.flights.find(f=>f.id===e.flight),divert=e.action==='divert',remote=s.ground.stands[e.stand]?.kind==='remote'||e.stand==='R1'&&!s.ground.stands[e.stand]?.kind;return `<article class="flight-confirmation"><span class="confirmation-number">${index+1}</span><div><div class="confirmation-heading"><b>${esc(f?.callsign||e.flight)}</b><span>${esc(RecoveryPresentation.carrier(f||{}))}</span><em>${divert?'DIVERSION':current.result.status==='FALLBACK'?'VALIDATED FALLBACK':'SUCCESS'}</em></div><p>${divert?`Divert to ${esc(e.alternate)} · estimated alternate landing <b>${clock(e.landing,s)}</b>. Destination gate not assigned.`:`Land on ${esc(e.runway)} at <b>${clock(e.landing,s)}</b> → ${remote?'remote stand':'gate'} <b>${esc(e.stand)}</b> at <b>${clock(e.on_stand,s)}</b>.`}</p><small>${current.result.status==='CONSENSUS'?'All three domains accepted the shared plan.':'Selected by deterministic fallback; this is not agent consensus.'} Simulation only.</small></div></article>`;}
function renderFlightStory(s,v){const stage=playbackState(),box=$('#flightStory');if(current?.streaming)stage.agreed=false;box.hidden=!current?.result;if(!current?.result)return;const r=current.result;let html='<div class="story-heading"><div><span class="small-label">FLIGHT-BY-FLIGHT RECOVERY</span><h2>'+(!stage.agreed?'First, agree on the shared plan.':!stage.events.length?'No safe plan found.':stage.finished?'Your landing timeline.':'Confirming each flight.')+'</h2></div><span class="status-badge">'+(stage.events.length?stage.confirmed+' / '+stage.events.length:v.done?'ACTION REQUIRED':'AWAITING SAFE PLAN')+'</span></div>';
if(!stage.agreed)html+='<p class="story-help">The agents check the whole cohort before any flight gets a success confirmation. A gate or landing slot can affect every other aircraft.</p>';
else if(!stage.events.length){const blocks=RecoveryPresentation.blockers(r);html+=`<p class="story-help">${r.status==='NOT_EVALUATED'?(r.missing?.some(x=>x.startsWith('AI backend'))?'The AI backend did not return a complete result. No agent consensus or plan is claimed.':'Required operational data is missing or invalid, so the system cannot assess a plan.'):'None of the '+(r.policy?.candidates_considered||r.diagnostics?.candidates_checked||'generated')+' candidate plans passed every hard constraint.'} This simulation commits the cohort as one shared plan: a blocking constraint can prevent confirmations for every flight. No safety margin has been relaxed.</p><div class="blocked-scope">${r.diagnostics?'The evidence below describes the closest generated candidate. It is not an approved plan.':r.status==='NOT_EVALUATED'?'Complete the inputs below, then run recovery again.':'The evidence below comes from the last reviewed proposal.'} ${r.policy?.search_mode==='bounded'?'The search is bounded; this does not prove that every possible solution is infeasible.':''}</div><div class="blocker-list">${blocks.length?blocks.map(c=>`<article class="blocker"><span class="status-badge reject">${esc((c.domain||'validator').toUpperCase())}</span><div><b>${esc(c.label)}</b><p>${esc(c.evidence)}</p><small>Next step: ${esc(c.remedy)}</small></div></article>`).join(''):'<p class="story-help">Validation evidence is unavailable. No flight is confirmed. Open the message trace for the failure details.</p>'}</div><div class="blocked-actions"><button class="secondary" data-open-manifest>Review flight inputs →</button><button class="secondary" data-open-settings>Review runway, gates & teams →</button></div>`;}
else if(!stage.finished){html+='<p class="story-help">The shared plan is validated. Reviewing flights in landing order; these are simulated plan confirmations, not live clearances.</p>';html+=stage.confirmed?stage.events.slice(0,stage.confirmed).map((e,i)=>eventCard(e,i,s)).join(''):'<div class="story-wait">Plan agreed. Next: confirm the first flight.</div>';}
else{html+='<p class="story-help">Chronological groups of up to five flights. Groups are display pages, not simultaneous landings; every flight retains its individual separation and gate time. All times are local to '+esc(s.airport)+'.</p>';html+=RecoveryPresentation.groups(stage.events).map((group,g)=>`<section class="timeline-group"><div class="timeline-group-title"><b>Group ${g+1}</b><span>Flights ${g*5+1}–${g*5+group.length} · ${clock(group[0].landing,s)}–${clock(group.at(-1).landing,s)}</span></div>${group.map((e,i)=>eventCard(e,g*5+i,s)).join('')}</section>`).join('');}
box.innerHTML=html;}

function aiInstructions(){return `<h2>Run three independent Claude agents.</h2><p>The hosted dashboard runs deterministic rules. Real Claude calls require the local Python backend and your own server-side API configuration.</p><ol><li>Open the project checkout and configure <code>ANTHROPIC_API_KEY</code> and <code>ANTHROPIC_MODEL</code> in your terminal environment. Never put a key in this page or a CSV.</li><li>Run <code>python3 backend/server.py</code> from <code>ui-restored</code>.</li><li>Open <a href="http://127.0.0.1:8874/">the local dashboard</a> and select independent Claude agents.</li></ol><p>Each role has its own prompt, domain data and conversation history. Messages stream as responses arrive. Code checks retain veto power; three turns / 60 seconds maximum, then deterministic fallback or escalation. Missing or failed AI responses are never described as consensus.</p><p>No API credential is configured in this hosted Site. Live Claude execution has not been verified here.</p>`;}
async function runLive(){if(!readDisruption())return;if(!['127.0.0.1','localhost'].includes(location.hostname)){showInfo(aiInstructions());return;}readResources();if(!validResources())return;updateCount(true);updateStands(true);syncSidebar();stopPlayback();if(liveController)liveController.abort();const id=++jobId,s=clone(draft);s.state_version=revision;current={id:'RR-'+String(++sequence).padStart(3,'0'),scenario:s,options:{mode:'claude'},time:new Date().toLocaleTimeString('en-SG'),status:'LIVE AI',result:{status:'RUNNING',mode:'claude',plan:null,log:[]},streaming:true,live:true,complete:false};runs.push(current);if(runs.length>12)runs.shift();cursor=0;setTab('workspace');notice('Independent Claude agents are running on your local backend. Actual response messages stream below.');liveController=new AbortController();const controller=liveController,deadline=setTimeout(()=>controller.abort(),90000);render();try{const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:s,options:{failAgent:$('#outage').value||null}}),signal:controller.signal});if(!response.ok)throw Error(response.status===503?'The local backend needs ANTHROPIC_API_KEY and ANTHROPIC_MODEL.':`Local backend returned ${response.status}; use python3 backend/server.py on port 8874.`);const reader=response.body.getReader(),decoder=new TextDecoder();let pending='',gotResult=false;while(true){const part=await reader.read();pending+=decoder.decode(part.value||new Uint8Array(),{stream:!part.done});const lines=pending.split('\n');pending=lines.pop();for(const line of lines){if(!line.trim())continue;const item=JSON.parse(line);if(id!==jobId)return;if(item.type==='error')throw Error('Backend failure: '+item.error);if(item.type==='message'){current.result.log.push(item.message);cursor=current.result.log.length;render();}if(item.type==='result'){gotResult=true;current.result=item.result;current.result.analysis=RecoveryEngine.analyse(s,item.result,{repairs:false});current.streaming=false;current.status=item.result.status;cursor=item.result.log.length;render();if(playbackState().events.length)play();else{current.complete=true;render();}}}if(part.done)break;}if(!gotResult)throw Error('The AI stream ended without a validated result. No plan committed.');}catch(error){if(id===jobId){current.streaming=false;current.status='ERROR';current.result={status:'NOT_EVALUATED',mode:'claude',plan:null,log:current.result.log.length?current.result.log:[{type:'DATA_REQUIRED',sender:'validator',reason:error.message}],missing:['AI backend response incomplete: '+error.message]};cursor=current.result.log.length;current.complete=true;notice(error.message,true);render();}}finally{clearTimeout(deadline);if(liveController===controller)liveController=null;}}
$('#executionMode').onchange=()=>{invalidate('Execution mode changed. Previous approvals cleared.');if($('#executionMode').value==='claude'&&!['127.0.0.1','localhost'].includes(location.hostname))showInfo(aiInstructions());};
$('#briefBtn').onclick=()=>showInfo(`<h2>Challenge coverage, honestly.</h2><div class="coverage-row"><b>ATC — implemented within the configured airport model</b><p>Wake/radar separation, runway closures and blocked taxi routes are mandatory. Airport movement capacity from the workbook is a rolling-hour hard cap, including configured background traffic. Throughput and holding are soft objectives; full en-route sector geometry is outside this model.</p></div><div class="coverage-row"><b>Pilot — implemented within supplied assumptions</b><p>Protected destination/alternate/reserve fuel, assessed weather margins and reachable alternates are mandatory. Holding fuel, connections and configured turbulence exposure are soft objectives. Turbulence is a declared 0–3 scenario input, not live weather data.</p></div><div class="coverage-row"><b>Ground — implemented within the resource model</b><p>Stand compatibility/occupancy/buffers, turnaround minimums and crew budgets/capacity are mandatory. The workbook's 20-minute gate-change notice is mandatory. Gate use, 1.5× overtime after the eight-hour shift and turnaround departure delay are soft objectives.</p></div><div class="coverage-row"><b>Structured coordination and consensus — implemented</b><p>Independent role evaluators; versioned proposals, votes and counterproposals; unanimous same-version acceptance; trace export. Three turns and up to 192 candidates. Fallback is deterministic and must pass every hard rule. No valid candidate means escalation, never forced agreement.</p></div><div class="coverage-row"><b>DOT 2015 seed — verified on CSV import</b><p>Import the provided CSV to retain a complete qualifying seed row. The cached preview contains flight schedules but omits the raw row. A selected historical row must have WEATHER_DELAY &gt; 15 or LATE_AIRCRAFT_DELAY &gt; 20. When imported, the raw qualifying seed and provenance are passed to each Claude agent; actual arrival outcomes are historical context, not prediction inputs. Fuel, wake classes, gates, crews and turbulence remain explicitly simulated.</p></div><div class="coverage-row"><b>Real AI and real-time communication — local backend available, credential required</b><p>This hosted page defaults to deterministic simulation. The local backend uses separate Claude prompts and conversation histories, streams structured responses and retains code vetoes. No live ATC, aircraft or weather feed is connected. Live Claude has not been exercised without a configured API key.</p></div><p>Consensus is a goal, not a guarantee. Infeasible inputs, unavailable agents or missing evidence must end safely in fallback or escalation.</p><button id="aiSetupInfo" class="secondary">${'See backend setup instructions'}</button>`);
document.addEventListener('click',e=>{if(e.target.id==='aiSetupInfo')showInfo(aiInstructions());});

function workbookHTML(){const c=draft.constraint_sources,a=c.airport_limits;const rows=[['Active runways',draft.atc.runways.length,a.runways,a.sources.runways],['Total airport gates',draft.ground.total_gates,a.gates,a.sources.gates],['Recovery stand pool',Object.keys(draft.ground.stands).length,a.spare_gates,a.sources.spare_gates],['Airport movements / rolling hour',draft.atc.max_runway_ops_per_hour,a.movements_per_hour,a.sources.movements_per_hour],['Minimum turnaround (min)',draft.rules.minimum_turnaround_minutes,a.minimum_turnaround,a.sources.minimum_turnaround],['Final reserve (holding minutes)',draft.rules.protected_reserve_minutes,30,'fuel_and_crew!B2'],['Contingency (% planned trip fuel)',draft.rules.contingency_fraction*100,5,'fuel_and_crew!B3'],['Gate change notice (min)',draft.rules.gate_notice_minutes,20,'fuel_and_crew!B9']];return `<h2>Challenge workbook · ${esc(draft.airport)}</h2><p>These are synthetic planning limits from the supplied workbook. The earlier 45-minute cruise-reserve profile remains a separate legacy model; this challenge profile uses 30 minutes of holding fuel plus 5% trip contingency.</p><div class="table-wrap"><table><thead><tr><th>Limit</th><th>Current</th><th>Workbook</th><th>Source cell</th></tr></thead><tbody>${rows.map(([label,value,original,cell])=>`<tr><td>${esc(label)}</td><td>${fmt(value)} ${value!==original?'· OVERRIDE':''}</td><td>${fmt(original)}</td><td>${esc(cell)}</td></tr>`).join('')}</tbody></table></div><p>Holding burn: narrowbody 2,400 kg/h (fuel_and_crew!B4); widebody 6,500 kg/h (B5). Crew duty maximum 13h from report (B7). Ground shift 8h and 1.5× overtime (B8). Wake arrival NM and same-runway departure seconds: wake_separation!A4:D11.</p><h3>Declared scenario assumptions</h3><ul>${c.assumptions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Current ground teams: ${draft.ground.crew_capacity}; background movements reserved: ${draft.atc.background_ops_per_hour}/h; decision time: T${draft.atc.decision_time>=0?'+':''}${draft.atc.decision_time}. Per-flight edits are user-supplied overrides. All are retained in scenario and trace exports.</p><p><a href="challenge2_operational_constraints.xlsx" download>Download original constraints workbook</a> · Source SHA-256 ${esc(c.sha256)}</p>`;}
$('#workbookBtn').onclick=()=>showInfo(workbookHTML());$('#rulesBtn').onclick=()=>showInfo(workbookHTML());
function renderTurns(s,v){const proposals=v.messages.map((m,i)=>({m,i})).filter(x=>x.m.type==='PROPOSE');$('#turnBoard').innerHTML=[1,2,3].map(turn=>{const p=proposals.find(x=>x.m.round===turn),votes=p?v.messages.filter(m=>m.proposal_id===p.m.proposal.id&&m.turn===turn&&['ACCEPT','REJECT','ERROR'].includes(m.type)):[];return `<article class="turn-column ${p?'active':''}"><div class="turn-title"><b>Turn ${turn}</b><span>${v.done&&!p?'Not required':votes.length+' / 3 agent messages'}</span></div>${v.done&&!p?'<p class="table-note">Negotiation finished before this turn. No further agent messages are needed.</p>':Object.entries(roles).map(([role,meta])=>{const vote=votes.find(m=>m.sender===role);return `<div class="turn-vote"><span class="turn-role">${meta.tag}</span><div><b class="${vote?.type==='REJECT'?'negative':''}">${vote?esc(vote.type):'Awaiting message'}</b><p>${esc(vote?.reason||vote?.error||'One structured message per agent in this turn.')}</p>${vote?.offer?.adjustments?.length?`<small>Conditional offer: ${vote.offer.adjustments.slice(0,2).map(x=>esc(s.flights.find(f=>f.id===x.flight)?.callsign||x.flight)+' '+(x.arrival_delta_minutes>=0?'+':'')+fmt(x.arrival_delta_minutes)+' min → '+esc(x.to_stand)).join('; ')}. All three agents will automatically recheck this revised schedule for runway spacing, fuel and gate conflicts before it can be confirmed.</small>`:''}${vote?.concession?.startsWith('Accepting')?`<small>${esc(vote.concession)}</small>`:''}</div></div>`;}).join('')}${p?`<button class="text-button" data-turn-jump="${Math.min(v.log.length,p.i+4)}">Inspect this turn →</button>`:''}</article>`;}).join('');}
function renderComparison(s,v){const panel=$('#comparisonPanel');panel.hidden=!v.done;if(!v.done)return;const a=current.result.analysis;if(!a){panel.innerHTML='<div class="panel-title"><h2>Comparison unavailable: required inputs are incomplete.</h2></div>';return;}let html='<div class="panel-title"><div><span class="small-label">MEASURABLE TRADE-OFFS</span><h2>What changed through coordination?</h2></div></div><p class="plan-copy">Baseline: '+esc(a.baseline.name)+'. '+(a.baseline.valid?'Baseline passes the same hard checks.':'Baseline fails hard checks; no savings are claimed against an unsafe schedule.')+'</p>';if(a.change){html+='<div class="comparison-grid">'+[['Holding minutes',a.change.holding_minutes],['Holding fuel (kg)',a.change.holding_fuel_kg],['Missed connections',a.change.missed_connections],['Turnaround delay (min)',a.change.turnaround_delay]].map(([label,value])=>`<div><b>${value>0?'−':value<0?'+':''}${fmt(Math.abs(value),1)}</b><span>${label} vs feasible baseline</span></div>`).join('')+'</div>';}else if(!a.baseline.valid)html+='<p class="plan-copy">Baseline blockers: '+esc([...new Set(a.baseline.failures.map(c=>c.label))].slice(0,5).join('; '))+'.</p>';if(!current.result.plan){html+='<div class="repair-section"><h3>What resource change could unlock recovery?</h3><p>'+esc(a.repair_search||'Resource counterfactuals are available in rules simulation; they do not change the current plan.')+'</p>'+(a.repairs.length?a.repairs.slice(0,3).map(x=>`<article><b>${esc(x.description)}</b><p>A generated candidate passes every hard check under this hypothetical resource availability. Operator verification is required; no safety margin changed.</p></article>`).join(''):'<p>No successful resource change was found in the tested set. This does not establish global infeasibility.</p>')+'</div>';}html+='<p class="plan-copy">'+esc(a.scope)+'</p>';panel.innerHTML=html;}

function readDisruption(){const description=$('#disruptionReason').value.trim();if(!description){notice('Describe why the flight was disrupted, or choose a disruption row from flights.csv.',true);$('#disruptionReason').focus();return false;}draft.disruption={...draft.disruption,description};return true;}
$('#disruptionReason').oninput=()=>{draft.disruption={...draft.disruption,source:draft.disruption?.source==='dot'?'dot':'manual',description:$('#disruptionReason').value.trim(),user_edited:true};invalidate('Disruption description updated. The agents will receive it on the next run. Operational limits remain set by the numeric inputs.');};
$('#disruptionCsvBtn').onclick=chooseCSV;
for(const [id,key] of [['effectReopens','reopens'],['effectWeather','weather'],['effectEquipment','equipment']])$('#'+id).oninput=e=>{const value=e.target.value,control=$('[data-resource="'+key+'"]');control.value=value;readResources();invalidate('Operational effect updated. Previous approvals cleared.');};
